// Módulo Maestro de Datos Semilla Geoespaciales: 12 Rutas Principales de Tuxtla Gutiérrez, Chiapas
// Incluye geometrías viales separadas de IDA (outboundGeometry) y VUELTA (inboundGeometry) vía OSRM con offset lateral
// Sistema de Referencia Espacial: SRID 4326 (WGS 84)

/**
 * Cálculo geodésico Haversine exacto en metros entre dos coordenadas decimales
 */
export function calculateHaversineDistance(lat1, lon1, lat2, lon2) {
  const R = 6371e3; // Radio de la Tierra en metros
  const φ1 = (lat1 * Math.PI) / 180;
  const φ2 = (lat2 * Math.PI) / 180;
  const Δφ = ((lat2 - lat1) * Math.PI) / 180;
  const Δλ = ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
    Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return Math.round(R * c * 10) / 10;
}

